style.css:
@-moz-document domain("yandex.ru") {
/* Красный фон для верхней панели поиска */
  .search2__inner {
    border: 2px solid #f00; /* Красная рамка */
    background-color: #000; /* Черный фон */
  }

  /* Красные рамки для вкладок */
  .tabs2__tab, .tabs2__tab.tabs2__tab_active {
    border: 2px solid #f00; /* Красная рамка */
    background-color: #000; /* Черный фон */
    color: #fff; /* Белый текст, чтобы было видно на черном */
  }

    /* Красные рамки для групп (если есть группы вкладок) */
    .tabs2__group {
        border: 2px solid #f00; /* Красная рамка */
        background-color: #000; /* Черный фон */
    }

    /* Красные рамки для активной вкладки */
    .tabs2__tab.tabs2__tab_active {
        border-bottom: 2px solid #f00; /* Красная рамка снизу для активной вкладки (можно изменить на все стороны) */
    }

    /* Дополнительные стили для лучшего отображения */
    .tabs2__tab:hover, .tabs2__tab_active:hover {
        background-color: #333; /* Более темный фон при наведении */
    }
}
